      whenNotToUse: 'Darkroom הוא הכלי הלא נכון לעבודה של צעד אחד. אם אתם צריכים רק לחתוך את ההתחלה והסוף של קליפ, לשנות את הפורמט שלו או להקטין אותו, דפי חיתוך הווידאו ודחיסת הווידאו הייעודיים עושים זאת בהעלאה אחת ובלי פרויקט. זה גם לא מקום לצילומים שאינכם יכולים להעלות: כל מקור נשלח לשרת שלנו ליצירת פרוקסי ולרינדור, ולכן חומר שלעולם אינו רשאי לעזוב את המחשב שלכם שייך לעורך שולחני. פרויקטים במפגש אורח מוגבלים לאחד ונשמרים 24 שעות; התחברו לפני שאתם מתחילים משהו שתרצו לחזור אליו בשבוע הבא.',
