      intro: 'תמלול וידאו לוקח MP4, MOV, WebM, MKV או קובץ אודיו רגיל, מפריד את רצועת האודיו, ומריץ אותה דרך Whisper על שרת GPU שאנחנו מפעילים. אתם בוחרים את צורת התוצאה לפני ההעלאה: קובץ כתוביות WebVTT או SRT עם תזמוני כתוביות, קובץ טקסט רגיל עם המילים בלבד, או מסמך JSON עם כל מקטע וזמן ההתחלה והסיום שלו עד לאלפית השנייה. השפה מזוהה אוטומטית, או שאפשר להקליד קוד של שתי אותיות כדי לקבוע אותה.',
