      intro: 'HTTP Live Streaming מגיש וידאו כפלייליסט של מקטעים קצרים בכמה רמות איכות, כך שנגן יכול להתחיל מהר ולהחליף רמות כשהחיבור משתנה. הפקת החבילה הזו ידנית פירושה קידוד כל רנדיציה עם קיפריימים מיושרים, פיצולן למקטעים, וכתיבת פלייליסט master שמתאר כל וריאנט בצורה נכונה. הדף הזה עושה את כל העבודה: הוא בודק את ההעלאה שלכם, מציע את רמות הסולם שהמקור והתוכנית שלכם מאפשרים, מקודד כל אחת מהן עם libx264 ו־AAC למקטעי MPEG-TS של 2 שניות, מוסיף לפי בחירה כתוביות ממתמלל ה־Whisper שלנו עצמנו, גיליון תמונות storyboard ופלייליסט I-frame לגלילה, ואורז הכול כ־tar.gz או zip שאפשר לפרוס על כל מארח סטטי.',
